import { headers } from 'next/headers'

// Response shapes are assumed — see the note in the PR description: no route
// handlers exist for these three endpoints in this repo yet.
type Analytics = { views: number; visitors: number }
type Notification = { id: string | number; message: string }
type Settings = { theme: string; emailNotifications: boolean }

// A server-side fetch needs an absolute URL, so the origin is built from the
// incoming request. Reading headers() also opts this route into dynamic
// rendering, which is what keeps these internal endpoints from being called
// during `next build`, when there is no server listening on them.
async function getRequestContext() {
  const headerList = await headers()
  const host = headerList.get('x-forwarded-host') ?? headerList.get('host')
  const protocol = headerList.get('x-forwarded-proto') ?? 'http'

  return {
    origin: `${protocol}://${host}`,
    // Forwarded so endpoints behind a session still resolve the current user.
    cookie: headerList.get('cookie'),
  }
}

async function getJson<T>(url: string, cookie: string | null): Promise<T | null> {
  try {
    // fetch is uncached by default in this version, so each request gets fresh
    // data. /api/settings could take `next: { revalidate: n }` if it turns out
    // not to be per-user.
    const res = await fetch(url, cookie ? { headers: { cookie } } : undefined)

    // fetch does not reject on 4xx/5xx, so the status needs an explicit check.
    if (!res.ok) return null

    return (await res.json()) as T
  } catch {
    // Degrade one panel instead of failing the whole dashboard.
    return null
  }
}

export default async function Dashboard() {
  const { origin, cookie } = await getRequestContext()

  // All three requests are initiated before anything is awaited, so they run in
  // parallel rather than in series.
  const [analytics, notifications, settings] = await Promise.all([
    getJson<Analytics>(`${origin}/api/analytics`, cookie),
    getJson<Notification[]>(`${origin}/api/notifications`, cookie),
    getJson<Settings>(`${origin}/api/settings`, cookie),
  ])

  return (
    <div>
      <h2>Dashboard Content</h2>

      <section>
        <h3>Analytics</h3>
        {analytics ? (
          <p>
            {analytics.views} views from {analytics.visitors} visitors
          </p>
        ) : (
          <p>Analytics unavailable</p>
        )}
      </section>

      <section>
        <h3>Notifications</h3>
        {!notifications ? (
          <p>Notifications unavailable</p>
        ) : notifications.length === 0 ? (
          <p>No notifications</p>
        ) : (
          <ul>
            {notifications.map((notification) => (
              <li key={notification.id}>{notification.message}</li>
            ))}
          </ul>
        )}
      </section>

      <section>
        <h3>Settings</h3>
        {settings ? (
          <ul>
            <li>Theme: {settings.theme}</li>
            <li>
              Email notifications: {settings.emailNotifications ? 'on' : 'off'}
            </li>
          </ul>
        ) : (
          <p>Settings unavailable</p>
        )}
      </section>
    </div>
  )
}

