        <h3>Settings</h3>
        {settings ? (
          <ul>
            <li>Theme: {settings.theme}</li>
            <li>
              Email notifications: {settings.emailNotifications ? 'on' : 'off'}
            </li>
          </ul>
        ) : (
          <p>Settings unavailable</p>
        )}
      </section>
    </div>
  )
}

